DATE = I.DATE
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
led = open(f'{ROOT}/logic/oral_triage/deu_32_haazinu_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M)); assert len(CI) == 312, len(CI)
def headv(p): return I.heads[p]
KEPT = [k for k in I.OUTSIDE if k not in I.EXCLUDED]; assert len(KEPT) == 11
def seat(k): return I.CITED[k][0]
def src(c, lo, hi):
    names = [f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p in I.PISKAOT if headv(p)[0] == c and lo <= headv(p)[1] <= hi for r in range(1, I.SPINE_ROWS[p] + 1)]
    names += [f'Sifrei Devarim {p}:{r}' for p, r in KEPT if seat((p, r))[0] == c and lo <= seat((p, r))[1] <= hi]
    for n in names: assert n in CI, n
    return '; '.join(names)
